// 連携の設定
static void AddAVAL(CACal *cp, int type, int pos, int sub, int with, double d, double dm)
{
	if( cp->amax >= AVMAX ) return;
	AVAL *ap = &cp->aval[cp->amax];
	ap->Type = type;
	ap->With = with;
	ap->Pos = pos;
	ap->SubPos = sub;
	if( cp->PitchUnit ){
		ap->DW = GetNormal(d / dm);
	}
	else {
		ap->DW = 100.0 / dm;
	}
	if( !ap->DW ) ap->DW = 0.001;
	ap->DMAX = 2000.0;
	if( (type == avWIRE) && (sub != 4) ){
		ap->DMIN = -2000.0;
	}
	else {
		ap->DMIN = 0.0;
	}
	cp->amax++;
}
